OnchainKit
AgentKit with Privy server wallet integration



The main technical integration shown in the document is between AgentKit and Privy server wallets, which enables:

Server-side wallet management through Privy
Automated blockchain interactions using AgentKit's action providers
Custom NFT minting with on-chain metadata storage using ERC721URIStorage
Gasless transactions for end users
Integration with Base Sepolia testnet

The document shows one key code example of the integration:
javascriptCopyasync function getAgentKitFromPrivy(privyWalletId: string) {
  const privyWallet = await privy.walletApi.getWallet({ id: privyWalletId });

  const account = await createViemAccount({
    walletId: privyWallet.id,
    address: privyWallet.address,
    privy,
  });

  const client = createWalletClient({
    account,
    chain: baseSepolia,
    transport: http(`https://lb.drpc.org/ogrpc?network=base-sepolia&dkey=${process.env.DRPC_API_KEY}`),
  });

  const walletProvider = new ViemWalletProvider(client);
  return await AgentKit.from({
    walletProvider,
    actionProviders: [wallet, cdp, erc721, erc721uristorage],
  });
}
And the custom ERC721URIStorage action provider:
javascriptCopyconst erc721uristorage = customActionProvider<EvmWalletProvider>({
  name: "erc721_uristorage",
  description: "Mint ERC721URIStorage NFTs",
  schema: mintParamsSchema,
  invoke: async (walletProvider, args) => {
    const { to, uri, contractAddress } = args;

    const abi = parseAbi([
      "function mint(address to, string memory uri) public returns (uint256)",
    ]);

    const data = encodeFunctionData({
      abi,
      functionName: "mint",
      args: [to, uri],
    });

    return await walletProvider.sendTransaction({
      to: contractAddress,
      data,
      value: BigInt(0),
    });
  },
});
